command:
// Neon Combat Manager: open the Plot Die (Raising the Stakes) for the selected token's character (or your own).
// Works from the hotbar, the Action HUD's Macros group, a Neon Hub page button or an active tile.
const ncm = game.modules.get("cpr-neon-combat-manager")?.api;
if (!ncm) return ui.notifications.warn("Neon Combat Manager isn't active in this world.");
const who = (typeof actor !== "undefined" && actor) || (typeof character !== "undefined" && character) || null;
return ncm.stakes.open(who);
